V = "ClickTime"
B = "https://www.clicktime.com/case-studies/"
NOTE = ("ClickTime case study, still live (sitemap lastmod 2025-12/2026). Pages carry 2022 migration dates; content is older. "
        "Brief record — domain/contacts not gathered (web search quota exhausted). ")
def r(slug, name, ind, country="US", seats="", status="PROBABLE", conf=55, summary="", **k):
    d = dict(company_name=name, industry=ind, hq_country=country, vendor=V, evidence_type="Vendor case study",
             evidence_summary=summary or ("ClickTime case study: %s uses ClickTime for time tracking." % name),
             source_url=B + slug, source_publication_date="", status=status,
             status_reason=k.pop("reason", "Live but older vendor story; current use not re-confirmed"), confidence_score=conf,
             estimated_tracked_seats=seats, employee_count=(seats + "+ tracking (story)") if seats else "",
             employee_count_source_url=B + slug if seats else "",
             pitch_angle="ClickTime is premium per-seat; Tavilo flat plans + activity tracking")
    d.update(k); d["notes"] = NOTE + k.get("notes", ""); return d
